class Solution {
public:
    long long countPairs(int n, std::vector<std::vector<int>>& edges) {
        std::vector<int> parent(n), size(n, 1);
        std::iota(parent.begin(), parent.end(), 0);
        auto find = [&](auto& self, int x) -> int {
            return parent[x] == x ? x : parent[x] = self(self, parent[x]);
        };
        for (const auto& e : edges) {
            int ru = find(find, e[0]), rv = find(find, e[1]);
            if (ru != rv) {
                if (size[ru] < size[rv]) std::swap(ru, rv);
                parent[rv] = ru;
                size[ru] += size[rv];
            }
        }
        long long total = (long long)n * (n - 1) / 2;
        long long reachable = 0;
        for (int i = 0; i < n; ++i) {
            if (parent[i] == i) {
                long long c = size[i];
                reachable += c * (c - 1) / 2;
            }
        }
        return total - reachable;
    }
};

class Solution {
    private int[] parent;
    private int[] size;
    private int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    public long countPairs(int n, int[][] edges) {
        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
        for (int[] e : edges) {
            int ru = find(e[0]), rv = find(e[1]);
            if (ru != rv) {
                if (size[ru] < size[rv]) {
                    int t = ru; ru = rv; rv = t;
                }
                parent[rv] = ru;
                size[ru] += size[rv];
            }
        }
        long total = (long) n * (n - 1) / 2;
        long reachable = 0;
        for (int i = 0; i < n; i++) {
            if (parent[i] == i) {
                long c = size[i];
                reachable += c * (c - 1) / 2;
            }
        }
        return total - reachable;
    }
}

var countPairs = function(n, edges) {
    const parent = new Int32Array(n);
    const size = new Int32Array(n).fill(1);
    for (let i = 0; i < n; i++) parent[i] = i;
    const find = (x) => {
        if (parent[x] !== x) parent[x] = find(parent[x]);
        return parent[x];
    };
    for (const [u, v] of edges) {
        let ru = find(u), rv = find(v);
        if (ru !== rv) {
            if (size[ru] < size[rv]) {
                const t = ru; ru = rv; rv = t;
            }
            parent[rv] = ru;
            size[ru] += size[rv];
        }
    }
    const total = BigInt(n) * BigInt(n - 1) / 2n;
    let reachable = 0n;
    for (let i = 0; i < n; i++) {
        if (parent[i] === i) {
            const c = BigInt(size[i]);
            reachable += c * (c - 1n) / 2n;
        }
    }
    return Number(total - reachable);
};
